<script lang="ts">
  import {page} from '$app/state';import {goto} from '$app/navigation';import type {AppData,Row} from '#lib/client/types.ts';import {display,recordName} from '#lib/client/api.ts';import Icon from './Icon.svelte';import Status from './Status.svelte';
  let {data}:{data:AppData}=$props();let mode=$state('week');let selectedDate=$state(new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Berlin'}).format(new Date()));let employee=$state('');
  const start=$derived.by(()=>{const d=new Date(selectedDate+'T12:00:00');if(mode==='week')d.setDate(d.getDate()-((d.getDay()+6)%7));return d;});const days=$derived(Array.from({length:mode==='week'?7:1},(_,i)=>{const date=new Date(start);date.setDate(date.getDate()+i);return {date,key:new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Berlin'}).format(date)};}));
  const assignments=$derived((data.records||[]).filter(r=>!employee||r.employee_id===employee));const unplanned=$derived(data.related?.unplanned_work_packages||[]);
  function dayKey(at:any){return at&&!Number.isNaN(Date.parse(at))?new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Berlin'}).format(new Date(at)):'';}
  function time(at:any){return at?new Intl.DateTimeFormat('de-DE',{hour:'2-digit',minute:'2-digit',timeZone:'Europe/Berlin'}).format(new Date(at)):'—';}
  function move(amount:number){const date=new Date(selectedDate+'T12:00:00');date.setDate(date.getDate()+amount*(mode==='week'?7:1));selectedDate=new Intl.DateTimeFormat('sv-SE').format(date);}
  function loadPeriod(){const from=days[0].key;const to=days.at(-1)!.key;goto('/dispatch?'+new URLSearchParams({from,to,...(employee?{employee_id:employee}:{})}));}
</script>
<section class="panel mb"><header class="panel-header"><div><h2>Einsätze im Überblick</h2><p>Planung nach Tag, Woche und Mitarbeiter. Änderungen öffnen Sie über den jeweiligen Einsatz.</p></div><div class="inline-actions"><button class="btn small" class:primary={mode==='day'} onclick={()=>mode='day'}>Tag</button><button class="btn small" class:primary={mode==='week'} onclick={()=>mode='week'}>Woche</button></div></header><div class="panel-body"><div class="toolbar"><button class="icon-button" aria-label="Vorheriger Zeitraum" onclick={()=>move(-1)}><Icon name="back" size={17}/></button><div class="field"><label class="sr-only" for="calendar-date">Datum</label><input id="calendar-date" type="date" bind:value={selectedDate}/></div><button class="icon-button" aria-label="Nächster Zeitraum" onclick={()=>move(1)}><Icon name="arrow" size={17}/></button><div class="field" style="min-width:190px"><label class="sr-only" for="calendar-team">Mitarbeiter filtern</label><select id="calendar-team" bind:value={employee}><option value="">Gesamtes berechtigtes Team</option>{#each data.lookups?.team||[] as person}<option value={person.id}>{person.name}</option>{/each}</select></div><button class="btn" onclick={loadPeriod}>Zeitraum laden</button></div><div class="calendar-scroll"><div class="calendar" class:day={mode==='day'}>{#each days as day}<section class="calendar-day" aria-label={new Intl.DateTimeFormat('de-DE',{dateStyle:'full'}).format(day.date)}><h3>{new Intl.DateTimeFormat('de-DE',{weekday:'short'}).format(day.date)} <span>{day.date.getDate().toString().padStart(2,'0')}</span></h3><div class="calendar-events">{#each assignments.filter(r=>dayKey(r.starts_at||r.start_at)===day.key).sort((a,b)=>String(a.starts_at).localeCompare(String(b.starts_at))) as assignment}<a class="calendar-event" href={`/dispatch/${assignment.id}`}><p class="event-time">{time(assignment.starts_at)} – {time(assignment.ends_at)}</p><h4>{recordName(assignment)}</h4><p>{display(assignment.employee_id,'employee_id',data)}</p>{#if assignment.location}<p>{assignment.location}</p>{/if}<Status value={assignment.status}/></a>{/each}{#if !assignments.some(r=>dayKey(r.starts_at||r.start_at)===day.key)}<p class="calendar-empty">Keine geladenen Einsätze</p>{/if}</div></section>{/each}</div></div><p class="field-help mt">Die Ansicht zeigt den geladenen berechtigten Bestand. „Zeitraum laden“ ruft die gewählte Periode ab. Verfügbarkeit und Doppelbelegung prüft der Server beim Speichern.</p></div></section>
{#if unplanned.length}<section class="panel mb"><header class="panel-header"><h2>Noch nicht eingeplante Arbeitspakete</h2><span class="count">{unplanned.length}</span></header><div class="panel-body">{#each unplanned as work}<a class="quick-link" href={`/work-packages/${work.id}`}><Icon name="briefcase" size={16}/>{recordName(work)}<span class="muted">{work.planned_hours?`${work.planned_hours} h geplant`:''}</span><Icon name="arrow" size={15}/></a>{/each}</div></section>{/if}
<style>.calendar-scroll{overflow:auto}.calendar{display:grid;grid-template-columns:repeat(7,minmax(130px,1fr));border:1px solid var(--line);border-radius:4px;overflow:hidden;min-height:260px}.calendar.day{grid-template-columns:1fr}.calendar-day+.calendar-day{border-left:1px solid var(--line)}.calendar-day h3{font-size:10px;padding:12px;background:#f9faf5;border-bottom:1px solid var(--line);color:var(--muted);font-weight:500;text-transform:uppercase;letter-spacing:.04em}.calendar-day h3 span{color:var(--ink);font-size:16px;margin-left:7px}.calendar-events{padding:8px;display:flex;flex-direction:column;gap:9px}.calendar-event{display:block;border:1px solid #d4dfce;background:#edf2e6;border-left:3px solid #718e65;border-radius:3px;padding:10px}.calendar-event h4{font-size:11px;font-weight:500;line-height:1.5;margin:5px 0}.calendar-event p{font-size:9px;margin-top:4px;line-height:1.5}.calendar-event .event-time{font-size:9px;color:#56724d;font-weight:500;margin:0}.calendar-event :global(.status){margin-top:8px}.calendar-empty{font-size:9px;padding:15px 4px;color:var(--muted)}@media(max-width:760px){.calendar{grid-template-columns:repeat(7,150px)}.calendar.day{min-width:100%;grid-template-columns:1fr}.calendar-day h3{font-size:11px}.calendar-event h4{font-size:13px}.calendar-event p,.calendar-event .event-time,.calendar-empty{font-size:11px}.calendar-event{padding:12px}.calendar-events{gap:11px;padding:10px}}</style>
